import listAllWarningByLoggedImpl from "./listAllWarningByLoggedImpl";

export const byCompany = (
    {
        offset = 0,
        limit = 50,
        //
        view = 'Employee',
        mon, mon2, mon3,
        expiry_date = 'ALL',
        removed = false,
        company_id,
        //
        department_id,
        job_position_id,
        team_id,
        supervisor_id,
        employee_id,
    }
) => {
    return listAllWarningByLoggedImpl({
        offset,
        limit,
        //
        view,
        mon, mon2, mon3,
        expiry_date,
        removed,
        org_id: {key: 'company_id', value: company_id},
        //
        department_id,
        job_position_id,
        team_id,
        supervisor_id,
        employee_id,
    });
};

